struct EvalItem: Identifiable {
    let id: String
    let title: String
    let prompt: String
    let output: String
    var reference: String? = nil
    let meta: String
}
struct Criterion: Identifiable {
    let id: String
    let label: String
    var detail: String? = nil
    var scale = 5
}
@Environment(\.monarchTheme) private var theme
private let items = [
    EvalItem(
        id: {{items.0.id}},
        title: {{items.0.title}},
        prompt: {{items.0.prompt}},
        output: {{items.0.output}},
        reference: {{items.0.reference}},
        meta: {{items.0.meta}}
    ),
    EvalItem(
        id: {{items.1.id}},
        title: {{items.1.title}},
        prompt: {{items.1.prompt}},
        output: {{items.1.output}},
        meta: {{items.1.meta}}
    ),
    EvalItem(
        id: {{items.2.id}},
        title: {{items.2.title}},
        prompt: {{items.2.prompt}},
        output: {{items.2.output}},
        meta: {{items.2.meta}}
    ),
]
private let rubric = [
    Criterion(id: {{rubric.0.id}}, label: {{rubric.0.label}}, detail: {{rubric.0.description}}),
    Criterion(id: {{rubric.1.id}}, label: {{rubric.1.label}}, detail: {{rubric.1.description}}),
    Criterion(id: {{rubric.2.id}}, label: {{rubric.2.label}}, scale: {{rubric.2.scale}}),
]
// Reviews by item id; persist every change in the app so no review is lost.
@State private var scores: [String: [String: Int]] = [:]
@State private var notes: [String: String] = [:]
@State private var verdicts: [String: String] = [:]
@State private var current: String? = {{items.0.id}}

private func score(_ item: String, _ criterion: String) -> Binding<Int?> {
    Binding(get: { scores[item]?[criterion] }, set: { scores[item, default: [:]][criterion] = $0 })
}

private func note(_ item: String) -> Binding<String> {
    Binding(get: { notes[item] ?? "" }, set: { notes[item] = $0 })
}

private func verdict(_ item: String) -> Binding<String?> {
    Binding(get: { verdicts[item] }, set: { verdicts[item] = $0 })
}

private func verdictText(_ item: String) -> String {
    switch verdicts[item] {
    case "pass": "Pass"
    case "fail": "Fail"
    default: "Not reviewed"
    }
}

