            Node(id: {{items.0.children.2.children.1.id}}, name: {{items.0.children.2.children.1.label}}, detail: {{items.0.children.2.children.1.description}}),
        ]),
    ]),
    Node(id: {{items.1.id}}, name: {{items.1.label}}, detail: {{items.1.description}}, children: [
        Node(id: {{items.1.children.0.id}}, name: {{items.1.children.0.label}}, detail: {{items.1.children.0.description}}),
